import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

// ─── ICONOS SVG PROFESIONALES ───
const Icons = {
  order: (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2"/><rect x="9" y="3" width="6" height="4" rx="2"/><path d="M9 14l2 2 4-4"/>
    </svg>
  ),
  kitchen: (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 21h18"/><path d="M5 21V7l8-4 8 4v14"/><path d="M9 21v-6a2 2 0 012-2h2a2 2 0 012 2v6"/><path d="M12 7v4"/>
    </svg>
  ),
  cashier: (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect x="2" y="6" width="20" height="12" rx="2"/><path d="M6 10h.01M6 14h.01"/><path d="M10 10h8"/><path d="M10 14h5"/>
    </svg>
  ),
  dashboard: (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/>
    </svg>
  ),
  reports: (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 3v18h18"/><path d="M7 16l4-4 4 4 6-8"/>
    </svg>
  ),
  reservations: (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4"/><path d="M8 2v4"/><path d="M3 10h18"/><path d="M8 14h.01"/><path d="M12 14h.01"/><path d="M16 14h.01"/><path d="M8 18h.01"/><path d="M12 18h.01"/><path d="M16 18h.01"/>
    </svg>
  ),
  menu: (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 7h18"/><path d="M3 12h18"/><path d="M3 17h18"/>
    </svg>
  ),
  categories: (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>
    </svg>
  ),
  modifiers: (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 00.33 1.82l.06.06a2 2 0 010 2.83 2 2 0 01-2.83 0l-.06-.06a1.65 1.65 0 00-1.82-.33 1.65 1.65 0 00-1 1.51V21a2 2 0 01-2 2 2 2 0 01-2-2v-.09A1.65 1.65 0 009 19.4a1.65 1.65 0 00-1.82.33l-.06.06a2 2 0 01-2.83 0 2 2 0 010-2.83l.06-.06A1.65 1.65 0 004.68 15a1.65 1.65 0 00-1.51-1H3a2 2 0 01-2-2 2 2 0 012-2h.09A1.65 1.65 0 004.6 9a1.65 1.65 0 00-.33-1.82l-.06-.06a2 2 0 010-2.83 2 2 0 012.83 0l.06.06A1.65 1.65 0 009 4.68a1.65 1.65 0 001-1.51V3a2 2 0 012-2 2 2 0 012 2v.09a1.65 1.65 0 001 1.51 1.65 1.65 0 001.82-.33l.06-.06a2 2 0 012.83 0 2 2 0 010 2.83l-.06.06a1.65 1.65 0 00-.33 1.82V9a1.65 1.65 0 001.51 1H21a2 2 0 012 2 2 2 0 01-2 2h-.09a1.65 1.65 0 00-1.51 1z"/>
    </svg>
  ),
  tables: (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect x="4" y="6" width="16" height="4" rx="1"/><path d="M6 10v8"/><path d="M18 10v8"/><path d="M6 18h12"/>
    </svg>
  ),
  users: (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87"/><path d="M16 3.13a4 4 0 010 7.75"/>
    </svg>
  ),
  logout: (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M9 21H5a2 2 0 01-2-2V5a2 2 0 012-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/>
    </svg>
  ),
  hamburger: (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 12h18"/><path d="M3 6h18"/><path d="M3 18h18"/>
    </svg>
  ),
  close: (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M18 6L6 18"/><path d="M6 6l12 12"/>
    </svg>
  ),
  logo: (
    <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 2v7c0 1.1.9 2 2 2h4a2 2 0 002-2V2"/><path d="M7 2v20"/><path d="M21 15V2v0a5 5 0 00-5 5v6c0 1.1.9 2 2 2h3Zm0 0v7"/>
    </svg>
  ),
  chevronDown: (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M6 9l6 6 6-6"/>
    </svg>
  ),
  moon: (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M21 12.79A9 9 0 1111.21 3 7 7 0 0021 12.79z"/>
    </svg>
  ),
  sun: (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="5"/><path d="M12 1v2"/><path d="M12 21v2"/><path d="M4.22 4.22l1.42 1.42"/><path d="M18.36 18.36l1.42 1.42"/><path d="M1 12h2"/><path d="M21 12h2"/><path d="M4.22 19.78l1.42-1.42"/><path d="M18.36 5.64l1.42-1.42"/>
    </svg>
  ),
};

// ─── PALETA DE COLORES (Documento Word) ───
const colors = {
  primary: '#E67E22',
  primaryHover: '#D36C1A',
  primaryPressed: '#B55912',
  textBase: '#333333',
  textSecondary: '#70757A',
  bgLight: '#FFFFFF',
  bgSecondary: '#F8F9FA',
  success: '#27AE60',
  warning: '#F1C40F',
  error: '#E74C3C',
  label: '#3498DB',
  // Dark Mode
  darkBg: '#121212',
  darkSurface: '#1E1E1E',
  darkTextBase: '#FFFFFF',
  darkTextSecondary: '#B0BEC5',
};

const DashboardLayout = ({ children }) => {
  const { user, logout, isAdmin, isManager, isCashier, isChef, isWaiter } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(false);
  const [darkMode, setDarkMode] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);

  // Detectar tamaño de pantalla (breakpoint en 1024px)
  useEffect(() => {
    const checkScreen = () => {
      setIsMobile(window.innerWidth < 1024);
      if (window.innerWidth >= 1024) setIsMobileOpen(false);
    };
    checkScreen();
    window.addEventListener('resize', checkScreen);
    return () => window.removeEventListener('resize', checkScreen);
  }, []);

  // Detectar scroll para sombra en navbar
  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 10);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Cerrar menú al navegar en móvil
  useEffect(() => {
    setIsMobileOpen(false);
  }, [location.pathname]);

  // Cerrar dropdown de perfil al hacer click fuera
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (!e.target.closest('.profile-dropdown')) setProfileOpen(false);
    };
    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, []);

  const menuItems = [
    ...(isWaiter ? [{ path: '/waiter', icon: Icons.order, label: 'Tomar Pedido' }] : []),
    ...(isChef ? [{ path: '/kitchen', icon: Icons.kitchen, label: 'Cocina' }] : []),
    ...(isCashier ? [{ path: '/cashier', icon: Icons.cashier, label: 'Caja' }] : []),
    ...(isManager ? [
      { path: '/admin/dashboard', icon: Icons.dashboard, label: 'Dashboard' },
      { path: '/admin/reports', icon: Icons.reports, label: 'Reportes' },
      { path: '/admin/reservations', icon: Icons.reservations, label: 'Reservas' },
      { path: '/admin/menu', icon: Icons.menu, label: 'Gestionar Menú' },
      { path: '/admin/categories', icon: Icons.categories, label: 'Categorías' },
      { path: '/admin/modifiers', icon: Icons.modifiers, label: 'Modificadores' },
      { path: '/admin/tables', icon: Icons.tables, label: 'Mesas' },
    ] : []),
    ...(isAdmin ? [
      { path: '/admin/users', icon: Icons.users, label: 'Usuarios' },
    ] : []),
  ];

  const isActive = (path) => location.pathname === path || location.pathname.startsWith(path + '/');

  // ─── ESTILOS DINÁMICOS ───
  const theme = darkMode ? {
    bg: colors.darkBg,
    surface: colors.darkSurface,
    text: colors.darkTextBase,
    textSec: colors.darkTextSecondary,
    border: '#2D2D2D',
    navBg: colors.darkSurface,
    hoverBg: 'rgba(230, 126, 34, 0.12)',
    activeBg: 'rgba(230, 126, 34, 0.18)',
    shadow: '0 4px 20px rgba(0,0,0,0.5)',
  } : {
    bg: colors.bgLight,
    surface: colors.bgLight,
    text: colors.textBase,
    textSec: colors.textSecondary,
    border: '#E8E8E8',
    navBg: colors.bgLight,
    hoverBg: 'rgba(230, 126, 34, 0.06)',
    activeBg: 'rgba(230, 126, 34, 0.10)',
    shadow: '0 4px 20px rgba(0,0,0,0.08)',
  };

  // ─── COMPONENTE: ITEM DE NAVEGACIÓN ───
  const NavItem = ({ item, isSidebar = false }) => {
    const active = isActive(item.path);
    return (
      <button
        onClick={() => navigate(item.path)}
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: isSidebar ? 14 : 10,
          padding: isSidebar ? '14px 18px' : '10px 16px',
          borderRadius: 12,
          border: 'none',
          background: active ? theme.activeBg : 'transparent',
          color: active ? colors.primary : theme.textSec,
          fontSize: isSidebar ? 15 : 14,
          fontWeight: active ? 600 : 500,
          cursor: 'pointer',
          transition: 'all 0.25s cubic-bezier(0.4, 0, 0.2, 1)',
          width: isSidebar ? '100%' : 'auto',
          textAlign: 'left',
          whiteSpace: 'nowrap',
          position: 'relative',
        }}
        onMouseEnter={(e) => {
          if (!active) e.currentTarget.style.background = theme.hoverBg;
          e.currentTarget.style.color = active ? colors.primaryHover : colors.primary;
        }}
        onMouseLeave={(e) => {
          if (!active) e.currentTarget.style.background = 'transparent';
          e.currentTarget.style.color = active ? colors.primary : theme.textSec;
        }}
      >
        <span style={{
          display: 'flex',
          color: active ? colors.primary : 'inherit',
          transition: 'color 0.25s',
        }}>
          {item.icon}
        </span>
        {item.label}
        {active && isSidebar && (
          <span style={{
            position: 'absolute',
            left: 0,
            top: '50%',
            transform: 'translateY(-50%)',
            width: 3,
            height: 24,
            background: colors.primary,
            borderRadius: '0 4px 4px 0',
          }}/>
        )}
      </button>
    );
  };

  // ─── RENDER ───
  return (
    <div style={{
      minHeight: '100vh',
      background: theme.bg,
      color: theme.text,
      transition: 'background 0.3s, color 0.3s',
    }}>
      {/* ═══════════════════════════════════════
          MENÚ SUPERIOR — VERSIÓN PC (≥1024px)
          ═══════════════════════════════════════ */}
      {!isMobile && (
        <header style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          zIndex: 100,
          background: scrolled ? theme.navBg : 'transparent',
          backdropFilter: scrolled ? 'blur(20px)' : 'none',
          WebkitBackdropFilter: scrolled ? 'blur(20px)' : 'none',
          borderBottom: scrolled ? `1px solid ${theme.border}` : '1px solid transparent',
          transition: 'all 0.3s ease',
          boxShadow: scrolled ? theme.shadow : 'none',
        }}>
          <div style={{
            maxWidth: 1400,
            margin: '0 auto',
            padding: '0 32px',
            height: 72,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}>
            {/* Logo */}
            <div style={{
              display: 'flex',
              alignItems: 'center',
              gap: 12,
              cursor: 'pointer',
            }} onClick={() => navigate('/')}>
              <div style={{
                width: 40,
                height: 40,
                borderRadius: 12,
                background: `linear-gradient(135deg, ${colors.primary}, ${colors.primaryHover})`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: '#fff',
                boxShadow: `0 4px 14px ${colors.primary}40`,
              }}>
                {Icons.logo}
              </div>
              <div>
                <h1 style={{
                  fontSize: 18,
                  fontWeight: 700,
                  color: theme.text,
                  letterSpacing: '-0.5px',
                  lineHeight: 1.2,
                  margin: 0,
                }}>
                  Restaurant <span style={{ color: colors.primary }}>AR</span>
                </h1>
                <p style={{
                  fontSize: 11,
                  color: theme.textSec,
                  margin: 0,
                  letterSpacing: '0.5px',
                  textTransform: 'uppercase',
                }}>
                  Sistema de Gestión
                </p>
              </div>
            </div>

            {/* Navegación Central */}
            <nav style={{
              display: 'flex',
              alignItems: 'center',
              gap: 4,
              flex: 1,
              justifyContent: 'center',
              padding: '0 24px',
            }}>
              {menuItems.map((item) => (
                <NavItem key={item.path} item={item} />
              ))}
            </nav>

            {/* Acciones Derecha */}
            <div style={{
              display: 'flex',
              alignItems: 'center',
              gap: 12,
            }}>
              {/* Toggle Dark Mode */}
              <button
                onClick={() => setDarkMode(!darkMode)}
                style={{
                  width: 38,
                  height: 38,
                  borderRadius: 10,
                  border: `1px solid ${theme.border}`,
                  background: 'transparent',
                  color: theme.textSec,
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  transition: 'all 0.2s',
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.borderColor = colors.primary;
                  e.currentTarget.style.color = colors.primary;
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.borderColor = theme.border;
                  e.currentTarget.style.color = theme.textSec;
                }}
              >
                {darkMode ? Icons.sun : Icons.moon}
              </button>

              {/* Perfil Dropdown */}
              <div className="profile-dropdown" style={{ position: 'relative' }}>
                <button
                  onClick={() => setProfileOpen(!profileOpen)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 10,
                    padding: '6px 14px 6px 6px',
                    borderRadius: 14,
                    border: `1px solid ${theme.border}`,
                    background: profileOpen ? theme.hoverBg : 'transparent',
                    cursor: 'pointer',
                    transition: 'all 0.2s',
                  }}
                >
                  <div style={{
                    width: 34,
                    height: 34,
                    borderRadius: '50%',
                    background: `linear-gradient(135deg, ${colors.primary}, ${colors.primaryHover})`,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontWeight: 700,
                    color: '#fff',
                    fontSize: 13,
                    flexShrink: 0,
                  }}>
                    {user?.name?.charAt(0)?.toUpperCase()}
                  </div>
                  <div style={{ textAlign: 'left', lineHeight: 1.3 }}>
                    <p style={{
                      fontSize: 13,
                      fontWeight: 600,
                      color: theme.text,
                      margin: 0,
                      whiteSpace: 'nowrap',
                    }}>
                      {user?.name}
                    </p>
                    <p style={{
                      fontSize: 11,
                      color: theme.textSec,
                      margin: 0,
                    }}>
                      {user?.role?.name}
                    </p>
                  </div>
                  <span style={{
                    color: theme.textSec,
                    transform: profileOpen ? 'rotate(180deg)' : 'rotate(0)',
                    transition: 'transform 0.2s',
                    display: 'flex',
                  }}>
                    {Icons.chevronDown}
                  </span>
                </button>

                {/* Dropdown */}
                {profileOpen && (
                  <div style={{
                    position: 'absolute',
                    top: 'calc(100% + 8px)',
                    right: 0,
                    width: 220,
                    background: theme.surface,
                    border: `1px solid ${theme.border}`,
                    borderRadius: 14,
                    boxShadow: theme.shadow,
                    padding: 8,
                    zIndex: 200,
                    animation: 'dropdownIn 0.2s ease',
                  }}>
                    <div style={{
                      padding: '12px 14px',
                      borderBottom: `1px solid ${theme.border}`,
                      marginBottom: 4,
                    }}>
                      <p style={{ fontSize: 13, fontWeight: 600, color: theme.text, margin: 0 }}>
                        {user?.name}
                      </p>
                      <p style={{ fontSize: 11, color: theme.textSec, margin: '4px 0 0 0' }}>
                        {user?.email || user?.role?.name}
                      </p>
                    </div>
                    <button
                      onClick={logout}
                      style={{
                        width: '100%',
                        display: 'flex',
                        alignItems: 'center',
                        gap: 10,
                        padding: '10px 14px',
                        borderRadius: 10,
                        border: 'none',
                        background: 'transparent',
                        color: colors.error,
                        fontSize: 13,
                        fontWeight: 500,
                        cursor: 'pointer',
                        transition: 'all 0.2s',
                        textAlign: 'left',
                      }}
                      onMouseEnter={(e) => {
                        e.currentTarget.style.background = `${colors.error}10`;
                      }}
                      onMouseLeave={(e) => {
                        e.currentTarget.style.background = 'transparent';
                      }}
                    >
                      {Icons.logout}
                      Cerrar Sesión
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        </header>
      )}

      {/* ═══════════════════════════════════════
          MENÚ LATERAL — VERSIÓN MÓVIL/TABLET (<1024px)
          ═══════════════════════════════════════ */}
      {isMobile && (
        <>
          {/* Header Móvil */}
          <header style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            zIndex: 100,
            height: 64,
            background: theme.navBg,
            backdropFilter: 'blur(20px)',
            WebkitBackdropFilter: 'blur(20px)',
            borderBottom: `1px solid ${theme.border}`,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            padding: '0 20px',
            boxShadow: scrolled ? theme.shadow : 'none',
            transition: 'box-shadow 0.3s',
          }}>
            <div style={{
              display: 'flex',
              alignItems: 'center',
              gap: 10,
            }}>
              <div style={{
                width: 36,
                height: 36,
                borderRadius: 10,
                background: `linear-gradient(135deg, ${colors.primary}, ${colors.primaryHover})`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: '#fff',
              }}>
                {Icons.logo}
              </div>
              <h1 style={{
                fontSize: 16,
                fontWeight: 700,
                color: theme.text,
                margin: 0,
              }}>
                Restaurant <span style={{ color: colors.primary }}>AR</span>
              </h1>
            </div>

            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <button
                onClick={() => setDarkMode(!darkMode)}
                style={{
                  width: 36,
                  height: 36,
                  borderRadius: 10,
                  border: `1px solid ${theme.border}`,
                  background: 'transparent',
                  color: theme.textSec,
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
              >
                {darkMode ? Icons.sun : Icons.moon}
              </button>
              <button
                onClick={() => setIsMobileOpen(!isMobileOpen)}
                style={{
                  width: 40,
                  height: 40,
                  borderRadius: 10,
                  border: `1px solid ${theme.border}`,
                  background: isMobileOpen ? theme.hoverBg : 'transparent',
                  color: theme.text,
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  transition: 'all 0.2s',
                }}
              >
                {isMobileOpen ? Icons.close : Icons.hamburger}
              </button>
            </div>
          </header>

          {/* Overlay */}
          {isMobileOpen && (
            <div
              onClick={() => setIsMobileOpen(false)}
              style={{
                position: 'fixed',
                inset: 0,
                background: 'rgba(0,0,0,0.4)',
                backdropFilter: 'blur(4px)',
                zIndex: 150,
                animation: 'fadeIn 0.3s ease',
              }}
            />
          )}

          {/* Sidebar Drawer */}
          <aside style={{
            position: 'fixed',
            top: 0,
            right: 0,
            bottom: 0,
            width: 300,
            maxWidth: '85vw',
            background: theme.surface,
            zIndex: 200,
            transform: isMobileOpen ? 'translateX(0)' : 'translateX(100%)',
            transition: 'transform 0.35s cubic-bezier(0.4, 0, 0.2, 1)',
            display: 'flex',
            flexDirection: 'column',
            boxShadow: '-4px 0 24px rgba(0,0,0,0.15)',
          }}>
            {/* Header Sidebar */}
            <div style={{
              padding: '20px 24px',
              borderBottom: `1px solid ${theme.border}`,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                <div style={{
                  width: 36,
                  height: 36,
                  borderRadius: 10,
                  background: `linear-gradient(135deg, ${colors.primary}, ${colors.primaryHover})`,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: '#fff',
                }}>
                  {Icons.logo}
                </div>
                <span style={{ fontWeight: 700, fontSize: 16, color: theme.text }}>
                  Menú
                </span>
              </div>
              <button
                onClick={() => setIsMobileOpen(false)}
                style={{
                  width: 36,
                  height: 36,
                  borderRadius: 10,
                  border: `1px solid ${theme.border}`,
                  background: 'transparent',
                  color: theme.textSec,
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
              >
                {Icons.close}
              </button>
            </div>

            {/* User Info */}
            <div style={{
              padding: '20px 24px',
              borderBottom: `1px solid ${theme.border}`,
              display: 'flex',
              alignItems: 'center',
              gap: 14,
            }}>
              <div style={{
                width: 48,
                height: 48,
                borderRadius: '50%',
                background: `linear-gradient(135deg, ${colors.primary}, ${colors.primaryHover})`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontWeight: 700,
                color: '#fff',
                fontSize: 16,
                flexShrink: 0,
                boxShadow: `0 4px 12px ${colors.primary}40`,
              }}>
                {user?.name?.charAt(0)?.toUpperCase()}
              </div>
              <div style={{ minWidth: 0 }}>
                <p style={{
                  fontSize: 15,
                  fontWeight: 600,
                  color: theme.text,
                  margin: 0,
                  whiteSpace: 'nowrap',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                }}>
                  {user?.name}
                </p>
                <p style={{
                  fontSize: 12,
                  color: theme.textSec,
                  margin: '4px 0 0 0',
                }}>
                  {user?.role?.name}
                </p>
              </div>
            </div>

            {/* Navegación */}
            <nav style={{
              flex: 1,
              padding: '16px 16px',
              overflowY: 'auto',
            }}>
              <p style={{
                fontSize: 11,
                fontWeight: 600,
                color: theme.textSec,
                textTransform: 'uppercase',
                letterSpacing: '1px',
                padding: '0 10px',
                marginBottom: 10,
              }}>
                Navegación
              </p>
              {menuItems.map((item) => (
                <NavItem key={item.path} item={item} isSidebar />
              ))}
            </nav>

            {/* Footer Sidebar */}
            <div style={{
              padding: '16px 20px',
              borderTop: `1px solid ${theme.border}`,
            }}>
              <button
                onClick={logout}
                style={{
                  width: '100%',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 12,
                  padding: '12px 16px',
                  borderRadius: 12,
                  border: `1px solid ${colors.error}30`,
                  background: 'transparent',
                  color: colors.error,
                  fontSize: 14,
                  fontWeight: 600,
                  cursor: 'pointer',
                  transition: 'all 0.2s',
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.background = `${colors.error}10`;
                  e.currentTarget.style.borderColor = `${colors.error}50`;
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.background = 'transparent';
                  e.currentTarget.style.borderColor = `${colors.error}30`;
                }}
              >
                {Icons.logout}
                Cerrar Sesión
              </button>
            </div>
          </aside>
        </>
      )}

      {/* ═══════════════════════════════════════
          CONTENIDO PRINCIPAL
          ═══════════════════════════════════════ */}
      <main style={{
        paddingTop: isMobile ? 64 : 72,
        minHeight: '100vh',
        transition: 'padding 0.3s',
      }}>
        <div style={{
          maxWidth: 1400,
          margin: '0 auto',
          padding: isMobile ? '20px 20px 40px' : '28px 32px 48px',
        }}>
          {children}
        </div>
      </main>

      {/* ═══════════════════════════════════════
          ESTILOS GLOBALES (ANIMACIONES)
          ═══════════════════════════════════════ */}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        @keyframes dropdownIn {
          from { opacity: 0; transform: translateY(-8px) scale(0.96); }
          to { opacity: 1; transform: translateY(0) scale(1); }
        }
        ::-webkit-scrollbar {
          width: 6px;
        }
        ::-webkit-scrollbar-track {
          background: transparent;
        }
        ::-webkit-scrollbar-thumb {
          background: ${theme.textSec}40;
          border-radius: 3px;
        }
        ::-webkit-scrollbar-thumb:hover {
          background: ${theme.textSec}60;
        }
      `}</style>
    </div>
  );
};

export default DashboardLayout;
